                    res = 1
                else:
                    res = 0

                if desc:
                    return -res
                return res

            filtered_rows = sorted(filtered_rows, key=functools.cmp_to_key(compare_rows))

    # 4. Limit
    if stmt.limit is not None:
        filtered_rows = filtered_rows[:stmt.limit]

    # 5. Projection
    results = []
    for row in filtered_rows:
        if stmt.columns is None:
            # Select *: shallow copy of table row
            results.append(dict(row))
        else:
            # Select list
            new_row = {}
            for col_name in stmt.columns:
                # Missing columns read as NULL
                new_row[col_name] = row.get(col_name)
            results.append(new_row)

    return results

def query(sql: str, tables: dict[str, list[dict]]) -> list[dict]:
    from minisql.parser import parse
    stmt = parse(sql)
    return execute(stmt, tables)
