# minisql/parser.py
from __future__ import annotations
from dataclasses import dataclass, field
from typing import Optional, Union
from minisql.tokens import Token, tokenize, SQLSyntaxError

# --- Syntax Tree Classes ---

@dataclass(frozen=True)
class Column:
    name: str

@dataclass(frozen=True)
class Literal:
    value: Union[int, float, str, bool, None]

@dataclass(frozen=True)
class Compare:
    op: str
    left: Union[Column, Literal]
    right: Union[Column, Literal]

@dataclass(frozen=True)
class And:
    left: Union[Compare, And, Or, Not, IsNull]
    right: Union[Compare, And, Or, Not, IsNull]

@dataclass(frozen=True)
class Or:
    left: Union[Compare, And, Or, Not, IsNull]
    right: Union[Compare, And, Or, Not, IsNull]

@dataclass(frozen=True)
class Not:
    operand: Union[Compare, And, Or, Not, IsNull]

@dataclass(frozen=True)
class IsNull:
    operand: Union[Column, Literal]
    negated: bool

@dataclass(frozen=True)
class Select:
    columns: Optional[list[str]]
    table: str
    where: Optional[Union[Compare, And, Or, Not, IsNull]]
    order_by: list[tuple[str, bool]]
    limit: Optional[int]

# --- Parser ---

class Parser:
    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token:
        if self.pos >= len(self.tokens):
            return self.tokens[-1] # EOF
        return self.tokens[self.pos]

    def advance(self) -> Token:
        token = self.peek()
        if self.pos < len(self.tokens) - 1:
            self.pos += 1
        return token

    def expect(self, kind: str, value: Optional[str] = None) -> Token:
        token = self.peek()
        if token.kind != kind or (value is not None and token.value != value):
            expected = value if value is not None else kind
            raise SQLSyntaxError(
                f"Expected {expected}, got {token.kind} ('{token.value}')",
                token.pos
            )
        return self.advance()

    def parse(self) -> Select:
        # SELECT
        self.expect("KEYWORD", "SELECT")
        columns = self.parse_select_list()

        # FROM
        self.expect("KEYWORD", "FROM")
        table_token = self.expect("IDENT")
        table_name = table_token.value

        # WHERE (optional)
        where = None
        if self.peek().kind == "KEYWORD" and self.peek().value == "WHERE":
            self.advance()
            where = self.parse_condition()

        # ORDER BY (optional)
        order_by = []
        if self.peek().kind == "KEYWORD" and self.peek().value == "ORDER":
            self.advance()
            self.expect("KEYWORD", "BY")
            order_by = self.parse_order_by()

        # LIMIT (optional)
        limit = None
        if self.peek().kind == "KEYWORD" and self.peek().value == "LIMIT":
            self.advance()
            limit_token = self.expect("NUMBER")
            if not isinstance(limit_token.value, int) or limit_token.value < 0:
                raise SQLSyntaxError(
                    "LIMIT expects a non-negative integer",
                    limit_token.pos
                )
            limit = limit_token.value

        # End of statement
        if self.peek().kind != "EOF":
            raise SQLSyntaxError(
                f"Unexpected token '{self.peek().value}'",
                self.peek().pos
            )

        return Select(columns, table_name, where, order_by, limit)

    def parse_select_list(self) -> Optional[list[str]]:
        if self.peek().kind == "STAR":
            self.advance()
            return None

        columns = []
        seen = set()

        while True:
            token = self.expect("IDENT")
            if token.value in seen:
                raise SQLSyntaxError(
                    f"Duplicate column name '{token.value}'",
                    token.pos
                )
            seen.add(token.value)
            columns.append(token.value)

            if self.peek().kind == "COMMA":
                self.advance()
            else:
                break

        return columns

    def parse_condition(self):
        # OR has lowest precedence
        node = self.parse_and_condition()
        while self.peek().kind == "KEYWORD" and self.peek().value == "OR":
            self.advance()
            right = self.parse_and_condition()
            node = Or(node, right)
        return node

    def parse_and_condition(self):
        # AND has higher precedence than OR
        node = self.parse_not_condition()
        while self.peek().kind == "KEYWORD" and self.peek().value == "AND":
            self.advance()
            right = self.parse_not_condition()
            node = And(node, right)
        return node

    def parse_not_condition(self):
        # NOT binds tighter than AND
        if self.peek().kind == "KEYWORD" and self.peek().value == "NOT":
            self.advance()
            operand = self.parse_not_condition()
            return Not(operand)
        return self.parse_atom_condition()

    def parse_atom_condition(self):
        token = self.peek()
        if token.kind == "LPAREN":
            self.advance()
            node = self.parse_condition()
            self.expect("RPAREN")
            return node

        # Parse left operand
        left = self.parse_operand()

        # Check for IS
        if self.peek().kind == "KEYWORD" and self.peek().value == "IS":
            self.advance()
            negated = False
            if self.peek().kind == "KEYWORD" and self.peek().value == "NOT":
                self.advance()
                negated = True
            self.expect("KEYWORD", "NULL")
            return IsNull(left, negated)

        # Check for Comparison Operator
        if self.peek().kind == "OP":
            op_token = self.advance()
            right = self.parse_operand()
            return Compare(op_token.value, left, right)

        # If we reach here, it's a bare operand, which is not a valid condition
        raise SQLSyntaxError(
            "Expected operator or IS after operand",
            self.peek().pos if self.peek().kind != 'EOF' else len(self.tokens[-1].value or '')
        )

    def parse_operand(self) -> Union[Column, Literal]:
        token = self.peek()
        if token.kind == "IDENT":
            self.advance()
            return Column(token.value)
        if token.kind == "NUMBER":
            self.advance()
            return Literal(token.value)
        if token.kind == "STRING":
            self.advance()
            return Literal(token.value)
        if token.kind == "KEYWORD":
            if token.value == "NULL":
                self.advance()
                return Literal(None)
            if token.value == "TRUE":
                self.advance()
                return Literal(True)
            if token.value == "FALSE":
                self.advance()
                return Literal(False)

        raise SQLSyntaxError(
            f"Expected operand, got {token.kind} ('{token.value}')",
            token.pos
        )

    def parse_order_by(self) -> list[tuple[str, bool]]:
        order_items = []
        while True:
            token = self.expect("IDENT")
            descending = False
            if self.peek().kind == "KEYWORD" and self.peek().value == "DESC":
                self.advance()
                descending = True
            elif self.peek().kind == "KEYWORD" and self.peek().value == "ASC":
                self.advance()
            order_items.append((token.value, descending))

            if self.peek().kind == "COMMA":
                self.advance()
            else:
                break
        return order_items

def parse(sql: str) -> Select:
    tokens = tokenize(sql)
    parser = Parser(tokens)
    return parser.parse()

