"""JSON Parser for js package."""

from .scanner import tokenize, Token, JSONError


def loads(text):
    """Parse a JSON string and return the corresponding Python object.

    Args:
        text (str): The JSON text to parse.

    Returns:
        The Python representation of the JSON value.

    Raises:
        JSONError: If the text is not valid JSON.
    """
    tokens = tokenize(text)
    if not tokens:
        # Should not happen as tokenize always returns at least EOF token
        raise JSONError("Empty input", 1, 1)

    parser = _Parser(tokens)
    value = parser.parse_value()
    parser.expect("EOF")
    return value


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    @property
    def current_token(self):
        return self.tokens[self.pos]

    def advance(self):
        """Advance to the next token."""
        if self.pos < len(self.tokens) - 1:
            self.pos += 1

    def error(self, msg, token=None):
        if token is None:
            token = self.current_token
        raise JSONError(msg, token.line, token.column)

    def expect(self, kind, msg=None):
        token = self.current_token
        if token.kind != kind:
            if msg is None:
                if kind == "EOF":
                    # For EOF, the error should point to current token if not EOF? 
                    # Spec says: "anything but whitespace after the top-level value: at its first character;"
                    # So if we expect EOF and see something else, that "something else" is the problem.
                    # The message should probably indicate unexpected content.
                    msg = "Unexpected content"
                else:
                    msg = f"Expected {kind}"
            self.error(msg, token)
        self.advance()

    def parse_value(self):
        token = self.current_token
        kind = token.kind

        if kind == "STRING":
            return self.parse_string_value(token)
        elif kind == "NUMBER":
            return self.parse_number_value(token)
        elif kind == "TRUE":
            self.advance()
            return True
        elif kind == "FALSE":
            self.advance()
            return False
        elif kind == "NULL":
            self.advance()
            return None
        elif kind == "{":
            return self.parse_object()
        elif kind == "[":
            return self.parse_array()
        else:
            self.error("Expected value", token)

    def parse_string_value(self, token):
        self.advance()
        return token.value

    def parse_number_value(self, token):
        self.advance()
        return token.value

    def parse_object(self):
        token = self.current_token
        assert token.kind == "{"
        self.advance()

        result = {}
        # Handle empty object
        if self.current_token.kind == "}":
            self.advance()
            return result

        while True:
            # Expect key (STRING)
            key_token = self.current_token
            if key_token.kind != "STRING":
                self.error("Expected object key", key_token)

            key = key_token.value
            self.advance()

            # Expect colon
            self.expect(":", "Expected colon")

            # Expect value
            value = self.parse_value()

            # Handle duplicate keys: keep last value, first position.
            # In Python 3.7+, dicts maintain insertion order. 
            # If we just assign result[key] = value, it updates the value but keeps original position
            # if the key already exists. This matches the requirement.
            result[key] = value

            # Expect comma or closing brace
            current = self.current_token
            if current.kind == ",":
                self.advance()
                # Check for trailing comma before closing brace
                if self.current_token.kind == "}":
                    self.error("Trailing comma", self.current_token)
                continue
            elif current.kind == "}":
                self.advance()
                break
            else:
                self.error("Expected ',' or '}'", current)

        return result

    def parse_array(self):
        token = self.current_token
        assert token.kind == "["
        self.advance()

        result = []
        # Handle empty array
        if self.current_token.kind == "]":
            self.advance()
            return result

        while True:
            # Expect value
            value = self.parse_value()
            result.append(value)

            # Expect comma or closing bracket
            current = self.current_token
            if current.kind == ",":
                self.advance()
                # Check for trailing comma before closing bracket
                if self.current_token.kind == "]":
                    self.error("Trailing comma", self.current_token)
                continue
            elif current.kind == "]":
                self.advance()
                break
            else:
                self.error("Expected ',' or ']'", current)

        return result
