import math
import struct


def dumps(obj, *, indent=None, sort_keys=False, ensure_ascii=False):
    """
    Serialize a Python object to a JSON string.
    """
    if indent is not None:
        if not isinstance(indent, int):
            raise TypeError("indent must be an int or None")
        if indent < 0:
            raise ValueError("indent must be non-negative")

    return _serialize(obj, indent=indent, level=0, sort_keys=sort_keys, 
                      ensure_ascii=ensure_ascii, seen=set())


def _serialize(obj, *, indent, level, sort_keys, ensure_ascii, seen):
    if obj is None:
        return "null"
    if obj is True:
        return "true"
    if obj is False:
        return "false"

    if isinstance(obj, (int, float)):
        return _serialize_number(obj)

    if isinstance(obj, str):
        return _serialize_string(obj, ensure_ascii)

    if isinstance(obj, (list, tuple)):
        return _serialize_array(obj, indent=indent, level=level, 
                                sort_keys=sort_keys, ensure_ascii=ensure_ascii, 
                                seen=seen)

    if isinstance(obj, dict):
        return _serialize_object(obj, indent=indent, level=level, 
                                 sort_keys=sort_keys, ensure_ascii=ensure_ascii, 
                                 seen=seen)

    raise TypeError(f"Object of type {type(obj).__name__} is not JSON serializable")


def _serialize_number(n):
    if isinstance(n, bool):
        # Should have been caught earlier, but just in case
        return "true" if n else "false"

    if isinstance(n, int):
        return str(n)

    if isinstance(n, float):
        if math.isnan(n) or math.isinf(n):
            raise ValueError("JSON does not support NaN or Infinity")

        # Python's repr for floats is mostly compatible with JSON,
        # but we need to be careful. repr(1.0) is '1.0', repr(1e308) is '1e+308'.
        # JSON allows '1.0', '1e308', etc.
        # The spec says: "A finite float becomes repr(f)"
        return repr(n)

    raise TypeError(f"Object of type {type(n).__name__} is not JSON serializable")


def _serialize_string(s, ensure_ascii):
    result = ['"']
    for ch in s:
        if ch == '"':
            result.append('\\"')
        elif ch == '\\':
            result.append('\\\\')
        elif ch == '\b':
            result.append('\\b')
        elif ch == '\f':
            result.append('\\f')
        elif ch == '\n':
            result.append('\\n')
        elif ch == '\r':
            result.append('\\r')
        elif ch == '\t':
